98	/// The single seam through which this executor changes state.
99	fn apply(
100	    state: &mut ReleaseExecutionStateV1,
101	    operation: &ReleaseOperationId,
102	    event: &OperationEvent,
103	) -> Result<(), GraphError> {
104	    state
105	        .apply(operation, event)
106	        .map(|_| ())
107	        .map_err(|source| match source {
108	            ReleaseStateError::EvidenceRejected(source) => GraphError::ReleaseProviderObservation { source },
109	            source => GraphError::ReleaseExecutionState { source },
110	        })
