113	/// Refuses to report success until every operation has an observed terminal
114	/// success state.
115	fn require_terminal_success(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<(), GraphError> {
116	    let count = intent
117	        .operations
118	        .iter()
119	        .filter(|operation| {
120	            !state
121	                .operation_state(operation.id())
122	                .is_some_and(OperationState::is_success)
123	        })
124	        .count();
125	    if count == 0 {
126	        Ok(())
127	    } else {
128	        Err(GraphError::ReleaseIncomplete { count })
129	    }
130	}
