154	/// Validates the serializable manifest independently of local byte and
155	/// attestation verification. Kept as a focused invariant helper for tests;
156	/// production execution requires `VerifiedArtifactManifest` above.
157	fn require_artifact_manifest_matches_intent(
158	    intent: &ReleaseIntentV1,
159	    artifacts: Option<&callisto_model::ArtifactManifestV1>,
160	) -> Result<(), GraphError> {
