172	/// The intent's operations as a DAG, built once per run. A constructed intent is already a proven DAG, so a failure
173	/// here means the intent was altered after validation.
174	pub(crate) fn operation_dag(intent: &ReleaseIntentV1) -> Result<Dag<ReleaseOperationId>, GraphError> {
175	    Dag::from_nodes(
176	        intent
177	            .operations
178	            .iter()
179	            .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec())),
180	        Order::Key,
181	    )
182	    .map_err(|violations| GraphError::ReleaseInvariant {
183	        detail: format!("the release operations do not form a valid DAG: {violations}"),
184	    })
