247	/// The pending operations that may start, in the intent's canonical order.
248	///
249	/// An operation may start when every one of its transitive prerequisites is `Published` or `AlreadySatisfied`. A
250	/// registry publish may also follow a registry publish that is only `issued`: npm takes a package whose dependency is
251	/// not visible yet, and everything announced (tag, release, uploads, publication) still waits for the version to be
252	/// shown. `ready` checks direct prerequisites; the ancestor check keeps a defective executor that recorded a later
253	/// operation's success before its prerequisite from making anything behind it eligible.
254	pub(crate) fn eligible_in(
255	    dag: &Dag<ReleaseOperationId>,
256	    state: &ReleaseExecutionStateV1,
257	    issued: &BTreeSet<ReleaseOperationId>,
258	) -> Vec<ReleaseOperationId> {
259	    let succeeded = |id: &ReleaseOperationId| state.operation_state(id).is_some_and(OperationState::is_success);
260	    dag.ready(
261	        |id| succeeded(id) || issued.contains(id),
262	        |id| state.operation_state(id) == Some(OperationState::Pending),
263	    )
264	    .filter_map(|ix| dag.key(ix).map(|id| (ix, id)))
265	    .filter(|(ix, id)| {
266	        dag.ancestors(&[*ix]).into_iter().all(|ancestor| {
267	            dag.key(ancestor).is_some_and(|prerequisite| {
268	                succeeded(prerequisite)
269	                    || (issued.contains(prerequisite) && is_registry_effect(id) && is_registry_effect(prerequisite))
270	            })
271	        })
272	    })
273	    .map(|(_, id)| id.clone())
274	    .collect()
275	}
