122	/// Adopting a version that is already published is by design (a rerun finishes a half-done release), but a version
123	/// whose registry entry names another repository is more likely someone else's package. Warns, never blocks.
124	fn warn_if_foreign_repository(
125	    adapter: &dyn RegistryEcosystem,
126	    context: &ProviderContext<'_>,
127	    id: &ReleaseOperationId,
128	    operation: &RegistryPublishOperation,
129	) {
130	    let Some(origin) = context.origin_endpoint() else {
131	        return;
132	    };
133	    let registry_repository = adapter.repository(context, operation);
134	    if let Some(warning) = repository::foreign_repository_warning(
135	        &id.package.to_string(),
136	        operation.version.render(),
137	        registry_repository.as_deref(),
138	        origin,
139	    ) {
140	        eprintln!("{warning}");
141	    }
142	}
143	
144	/// Runs the ecosystem's publish client. A failed publish stops here; a published and an already-existing version are
145	/// both left for the confirmation.
146	fn run_publish_client(
147	    adapter: &dyn RegistryEcosystem,
148	    context: &ProviderContext<'_>,
149	    request: &ProviderRequest<'_>,
150	    operation: &RegistryPublishOperation,
151	) -> Result<(), GraphError> {
152	    let output = adapter.publish(context, request.id, operation, request.artifacts)?;
153	    adapter
154	        .classify(&output)
155	        .map(|_outcome| ())
156	        .map_err(|source| GraphError::Registry {
157	            package: operation.package_name.clone(),
158	            source,
159	        })
160	}
161	
162	fn proceed() -> ReleasePreflight {
163	    ReleasePreflight::Proceed {
164	        proof: ProviderObservationV1::Absent
165	            .absent_proof()
166	            .expect("an absent observation mints an absent proof"),
167	    }
168	}
169	
170	fn registry_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a RegistryPublishOperation, GraphError> {
171	    match request.operation {
172	        PreparedOperation::RegistryPublish(operation) => Ok(operation),
173	        _ => Err(wrong_role(request.id, "registry publish")),
174	    }
175	}
176	
177	/// The one registry observation used by preflight and post-publish
178	/// confirmation, so the two can never disagree.
179	fn registry_observation<A: RegistryEcosystem + ?Sized>(
180	    adapter: &A,
181	    context: &ProviderContext<'_>,
182	    operation: &RegistryPublishOperation,
183	) -> Result<ProviderObservationV1, GraphError> {
184	    if !adapter.can_observe_versions() {
185	        return Ok(ProviderObservationV1::Indeterminate {
186	            cause: ProviderIndeterminateCause::UnsupportedProvider,
187	        });
188	    }
189	    policy::retry_observation(context.sleeper(), || adapter.observe_once(context, operation))
190	}
191	
192	/// The longest one publish command may run: the registry's configured `publish-timeout`, else the default.
193	fn publish_timeout(operation: &RegistryPublishOperation) -> Duration {
194	    operation.registry.publish_timeout.unwrap_or(timeouts::PUBLISH)
195	}
196	
197	/// How long this publish's version may take to show up: the registry's configured `confirm-timeout`, else the default.
198	fn visibility_window<A: RegistryEcosystem + ?Sized>(adapter: &A, operation: &RegistryPublishOperation) -> Duration {
199	    operation
200	        .registry
201	        .confirm_timeout
202	        .unwrap_or_else(|| policy::default_visibility_window(adapter.ecosystem()))
203	}
204	
205	/// The same observation, but an absence is treated as index-propagation lag
206	/// rather than an answer, for up to the registry's visibility window: this only
207	/// runs after a publish client reported the version as published or already there.
208	fn confirmed_registry_observation<A: RegistryEcosystem + ?Sized>(
209	    adapter: &A,
210	    context: &ProviderContext<'_>,
211	    operation: &RegistryPublishOperation,
212	) -> Result<ProviderObservationV1, GraphError> {
213	    policy::retry_within_window(context.sleeper(), visibility_window(adapter, operation), || {
214	        Ok(match adapter.observe_once(context, operation)? {
215	            Attempt::Settled(ProviderObservationV1::Absent) => Attempt::Transient {
216	                value: ProviderObservationV1::Absent,
217	                retry_after: None,
218	            },
219	            settled_or_transient => settled_or_transient,
220	        })
221	    })
222	}
223	
224	/// One ecosystem's registry client. This is the single place the release path
225	/// branches on [`Ecosystem`]: adding a registry means adding an adapter here,
226	/// not another match in preflight, dispatch, or confirmation.
227	pub(crate) trait RegistryEcosystem {
228	    fn ecosystem(&self) -> Ecosystem;
229	
230	    /// Whether a publish here is complete once the version is visible, so the run can issue the next publish while
231	    /// this one propagates. Not true where completion is more than visibility: PyPI compares a whole file set.
232	    fn defers_confirmation(&self) -> bool {
233	        false
234	    }
235	
236	    /// The repository the registry says this published version belongs to. Best effort: a registry that records
237	    /// none, or a read that fails, is `None`.
238	    fn repository(&self, _context: &ProviderContext<'_>, _operation: &RegistryPublishOperation) -> Option<String> {
239	        None
240	    }
241	
