22	/// Executes eligible operations one at a time.
23	///
24	/// The run `envelope` was created and validated before this call. Each
25	/// operation is observed once before any effect: an exact observation is
26	/// adopted as already satisfied, an absent one is published and confirmed,
27	/// and anything else stops the run before an effect is issued.
28	pub fn execute_release<P: ReleaseProviderSet + ?Sized>(
29	    capability: &P,
30	    permit: &ApplyPermit,
31	    envelope: &ReleaseRunEnvelopeV1,
32	    artifacts: Option<&VerifiedArtifactManifest<'_>>,
33	) -> Result<ReleaseExecutionStateV1, GraphError> {
34	    let intent = capability.intent();
35	    require_verified_artifact_manifest(intent, artifacts)?;
36	    envelope
37	        .validate_for_intent(intent)
38	        .map_err(|source| GraphError::ReleaseRunEnvelope { source })?;
39	    let mut state = ReleaseExecutionStateV1::new(intent, envelope.clone())
40	        .map_err(|source| GraphError::ReleaseExecutionState { source })?;
41	    let dag = operation_dag(intent)?;
42	    // Registry publishes issued but not yet seen on their registry; they stay `Attempting` until they are.
43	    let mut issued = BTreeSet::new();
44	    loop {
45	        let Some(operation) = eligible_in(&dag, &state, &issued).first().cloned() else {
46	            if issued.is_empty() {
47	                break;
48	            }
49	            settle_issued(capability, artifacts, &mut state, &mut issued)?;
50	            continue;
51	        };
52	        capability.recheck_trust()?;
53	        match capability.preflight(&operation, artifacts)? {
54	            ReleasePreflight::AlreadySatisfied { evidence } => {
55	                warn_if_registry_version_adopted(&operation);
56	                apply(
57	                    &mut state,
58	                    &operation,
59	                    &OperationEvent::ObservedExactBeforeEffect { evidence },
60	                )?;
61	            }
62	            ReleasePreflight::Proceed { proof } => {
63	                let attempt = OperationEvent::Attempt { proof };
64	                apply(&mut state, &operation, &attempt)?;
65	                // The proof stays borrowed from the recorded attempt: only an
66	                // attempt may authorize the effect that follows it.
67	                let OperationEvent::Attempt { proof } = &attempt else {
68	                    return Err(GraphError::ReleaseInvariant {
69	                        detail: "the attempt event just built is not an Attempt".to_owned(),
70	                    });
71	                };
72	                if capability.defers_confirmation(&operation) {
73	                    capability.issue(permit, proof, &operation, artifacts)?;
74	                    issued.insert(operation);
75	                } else {
76	                    let evidence = capability.publish(permit, proof, &operation, artifacts)?;
77	                    apply(&mut state, &operation, &OperationEvent::Confirmed { evidence })?;
78	                }
79	            }
80	        }
81	    }
82	    require_terminal_success(intent, &state)?;
83	    Ok(state)
84	}
