122	/// Adopting a version that is already published is by design (a rerun finishes a half-done release), but a version
123	/// whose registry entry names another repository is more likely someone else's package. Warns, never blocks.
124	fn warn_if_foreign_repository(
125	    adapter: &dyn RegistryEcosystem,
126	    context: &ProviderContext<'_>,
127	    id: &ReleaseOperationId,
128	    operation: &RegistryPublishOperation,
129	) {
130	    let Some(origin) = context.origin_endpoint() else {
131	        return;
132	    };
133	    let registry_repository = adapter.repository(context, operation);
134	    if let Some(warning) = repository::foreign_repository_warning(
135	        &id.package.to_string(),
136	        operation.version.render(),
137	        registry_repository.as_deref(),
138	        origin,
139	    ) {
140	        eprintln!("{warning}");
141	    }
142	}
