144	/// Runs the ecosystem's publish client. A failed publish stops here; a published and an already-existing version are
145	/// both left for the confirmation.
146	fn run_publish_client(
147	    adapter: &dyn RegistryEcosystem,
148	    context: &ProviderContext<'_>,
149	    request: &ProviderRequest<'_>,
150	    operation: &RegistryPublishOperation,
151	) -> Result<(), GraphError> {
152	    let output = adapter.publish(context, request.id, operation, request.artifacts)?;
153	    adapter
154	        .classify(&output)
155	        .map(|_outcome| ())
156	        .map_err(|source| GraphError::Registry {
157	            package: operation.package_name.clone(),
158	            source,
159	        })
160	}
