192	/// The longest one publish command may run: the registry's configured `publish-timeout`, else the default.
193	fn publish_timeout(operation: &RegistryPublishOperation) -> Duration {
194	    operation.registry.publish_timeout.unwrap_or(timeouts::PUBLISH)
195	}
196	
197	/// How long this publish's version may take to show up: the registry's configured `confirm-timeout`, else the default.
198	fn visibility_window<A: RegistryEcosystem + ?Sized>(adapter: &A, operation: &RegistryPublishOperation) -> Duration {
199	    operation
200	        .registry
201	        .confirm_timeout
202	        .unwrap_or_else(|| policy::default_visibility_window(adapter.ecosystem()))
203	}
