    for pkg in out.severities.keys().cloned().collect::<Vec<_>>() {
        let deps: Vec<DepEdge> = input.graph.dependencies_of(&pkg).cloned().collect();
        for edge in deps {
            if edge.kind == DepKind::Dev {
                continue;
            }
            if matches!(
                edge.spec,
                DepSpec::Workspace(_) | DepSpec::Catalog(_) | DepSpec::Opaque(_)
            ) {
